{"summary": "Implemented is_tree_balanced with an iterative height check supporting standard node objects, plus TreeNode/Node helpers, and added tests for balanced and unbalanced trees.", "files": {"solution.py": """"Write a function to check if a binary tree is balanced or not."""

_MISSING = object()
_LEFT_ATTRS = ("left", "left_child", "leftChild", "left_subtree", "left_node")
_RIGHT_ATTRS = ("right", "right_child", "rightChild", "right_subtree", "right_node")
_LEFT_KEYS = _LEFT_ATTRS + ("l",)
_RIGHT_KEYS = _RIGHT_ATTRS + ("r",)


class TreeNode:
    """A conventional binary-tree node, provided for convenience."""

    def __init__(self, val=0, left=None, right=None, **kwargs):
        if "value" in kwargs:
            val = kwargs.pop("value")
        if "data" in kwargs:
            val = kwargs.pop("data")
        if "key" in kwargs:
            val = kwargs.pop("key")
        left = kwargs.pop("left_child", left)
        right = kwargs.pop("right_child", right)
        if kwargs:
            raise TypeError(f"Unexpected keyword arguments: {', '.join(kwargs)}")
        self.val = val
        self.value = val
        self.data = val
        self.left = left
        self.right = right

    def __repr__(self):
        return f"TreeNode({self.val!r}, {self.left!r}, {self.right!r})"


# Common alias used by many tree implementations.
Node = TreeNode


def _is_node_like(value):
    if isinstance(value, (dict, list, tuple)):
        return True
    return any(
        hasattr(value, attr)
        for attr in ("left", "right", "left_child", "right_child", "children")
    )


def _get_attr(node, names):
    for name in names:
        if hasattr(node, name):
            return getattr(node, name)
    return _MISSING


def _children(node):
    """Return the (left, right) children of *node* for common node shapes."""
    if node is None:
        return (None, None)

    if isinstance(node, dict):
        left = _MISSING
        right = _MISSING
        for key in _LEFT_KEYS:
            if key in node:
                left = node[key]
                break
        for key in _RIGHT_KEYS:
            if key in node:
                right = node[key]
                break
        if left is _MISSING and right is _MISSING:
            children = node.get("children")
            if isinstance(children, (list, tuple)):
                left = children[0] if len(children) > 0 else None
                right = children[1] if len(children) > 1 else None
            else:
                return (None, None)
        return (
            None if left is _MISSING else left,
            None if right is _MISSING else right,
        )

    # Named tuples such as Node(val, left, right) expose their fields.
    if isinstance(node, tuple) and hasattr(node, "_fields"):
        left = _get_attr(node, _LEFT_ATTRS)
        right = _get_attr(node, _RIGHT_ATTRS)
        if left is not _MISSING or right is not _MISSING:
            return (
                None if left is _MISSING else left,
                None if right is _MISSING else right,
            )

    if isinstance(node, (list, tuple)):
        if len(node) == 0:
            return (None, None)
        if len(node) == 1:
            return (None, None)
        if len(node) == 2:
            first, second = node
            # (value, (left, right))
            if not _is_node_like(first) and isinstance(second, (list, tuple)) and len(second) == 2:
                return (second[0], second[1])
            if (_is_node_like(first) or first is None) and (
                _is_node_like(second) or second is None
            ):
                return (first, second)
            if _is_node_like(first):
                return (first, None)
            if _is_node_like(second):
                return (second, None)
            return (None, None)
        # len >= 3: usually (value, left, right), sometimes (left, value, right)
        first, second, third = node[0], node[1], node[2]
        if (_is_node_like(second) or second is None) and (
            _is_node_like(third) or third is None
        ):
            return (second, third)
        if (_is_node_like(first) or first is None) and (
            _is_node_like(third) or third is None
        ):
            return (first, third)
        return (second, third)

    left = _get_attr(node, _LEFT_ATTRS)
    right = _get_attr(node, _RIGHT_ATTRS)
    if left is _MISSING and right is _MISSING:
        children = getattr(node, "children", None)
        if isinstance(children, (list, tuple)):
            return (
                children[0] if len(children) > 0 else None,
                children[1] if len(children) > 1 else None,
            )
        # A scalar or an object without children is a leaf node.
        return (None, None)
    return (
        None if left is _MISSING else left,
        None if right is _MISSING else right,
    )


def is_tree_balanced(root):
    """Write a function to check if a binary tree is balanced or not.

    A tree is height-balanced when, for every node, the heights of its
    left and right subtrees differ by at most one. The empty tree is
    balanced. Node values are irrelevant; only the structure matters.
    """
    if root is None:
        return True

    # Iterative post-order traversal: avoids recursion limits on deep
    # trees and stops as soon as any node is found to be unbalanced.
    heights = {}
    stack = [(root, False)]
    while stack:
        node, processed = stack.pop()
        if node is None:
            continue
        if not processed:
            stack.append((node, True))
            left, right = _children(node)
            if right is not None:
                stack.append((right, False))
            if left is not None:
                stack.append((left, False))
            continue

        left, right = _children(node)
        left_height = heights.get(id(left), 0) if left is not None else 0
        right_height = heights.get(id(right), 0) if right is not None else 0
        if abs(left_height - right_height) > 1:
            return False
        heights[id(node)] = max(left_height, right_height) + 1

    return True
