def test_left_skewed_tree_is_unbalanced():
    assert is_tree_balanced(Node(1, Node(2, Node(3)))) is False


def test_right_skewed_tree_is_unbalanced():
    assert is_tree_balanced(Node(1, None, Node(2, None, Node(3)))) is False


