    # The root itself has equal-height subtrees, but ``unbalanced``
    # contains a node whose subtree heights differ by two.
    unbalanced = Node(9, Node(10, Node(11)), None)
    balanced_height_3 = Node(20, Node(21, Node(23), Node(24)), Node(22))
    root = Node(0, unbalanced, balanced_height_3)
    assert is_tree_balanced(root) is False


